package org.example.ui;
import org.example.dao.TaskDao;import org.example.model.User;import java.sql.SQLException;import java.util.Scanner;
public class EmployeeMenu {private final Scanner scanner;private final User user;private final TaskDao dao;public EmployeeMenu(Scanner s,User u,TaskDao d){scanner=s;user=u;dao=d;}public void start(){boolean run=true;while(run){System.out.println("\n========== TASKPILOT EMPLOYEE ==========");System.out.println("Logged in as: "+user.username());System.out.println("1. View My Assigned Tasks\n2. Update Task Status and Progress Notes\n0. Logout");System.out.print("Choose: ");switch(scanner.nextLine().trim()){case "1"->view();case "2"->update();case "0"->run=false;default->System.out.println("Invalid choice.");}}}private void view(){try{var ts=dao.getTasksForEmployee(user.id());System.out.printf("%4s | %-22s | %-8s | %-12s | %-12s | %s%n","ID","TASK","PRIORITY","DUE DATE","STATUS","NOTES");for(var t:ts)System.out.printf("%4d | %-22.22s | %-8s | %-12s | %-12s | %s%n",t.id(),t.name(),t.priority(),t.dueDate(),t.status(),t.progressNotes());if(ts.isEmpty())System.out.println("No assigned tasks.");}catch(SQLException e){System.out.println("Could not retrieve tasks: "+e.getMessage());}}private void update(){view();int id=readInt("Task ID to update (0 to cancel): ");if(id==0)return;System.out.print("New status (PENDING / IN PROGRESS / COMPLETED): ");String status=scanner.nextLine().trim().toUpperCase();if(!java.util.Set.of("PENDING","IN PROGRESS","COMPLETED").contains(status)){System.out.println("Invalid status.");return;}System.out.print("Progress notes: ");String notes=scanner.nextLine().trim();try{System.out.println(dao.updateTaskStatus(id,user.id(),status,notes)?"Task progress updated.":"Task not found in your assignments.");}catch(SQLException e){System.out.println("Could not update task: "+e.getMessage());}}private int readInt(String p){while(true){System.out.print(p);try{return Integer.parseInt(scanner.nextLine().trim());}catch(NumberFormatException e){System.out.println("Invalid input. Enter a number.");}}}}
